calls = []


def encode(message):
    calls.append("encode")
    return {
        "id": message["id"],
        "role": message["role"],
        "parts": [dict(part) for part in message["parts"]],
    }


def decode(stored):
    calls.append("decode")
    return {
        "id": stored["id"],
        "role": stored["role"],
        "parts": [dict(part) for part in stored["parts"]],
    }

